// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(amount > 0 && amount <= 1e30);

        // Ensure the contract is not paused
        assertFalse(c.paused(), "Contract should not be paused initially");

        // Call claim with the given parameters
        // We use try/catch to handle potential reverts (e.g., insufficient shares)
        try c.claim(sender, amount) {
            // If claim succeeded, the contract must remain not paused
            assertFalse(c.paused(), "Contract should not be paused after successful claim");
        } catch {
            // Even if claim reverts, paused state should still be false
            assertFalse(c.paused(), "Contract should not be paused even if claim reverts");
        }
    }
}

